// Func013_10_00 is a deterministically generated function
// for the repomap perf fixture; it references Func014_11_00
// so the pagerank/refs step in repomap.Build has real edges
// to walk, not an isolated file per symbol.
func Func013_10_00(a, b int) int {
	if a > b {
		return Func014_11_00(a, b) + a
	}
	return Func014_11_00(b, a) - b
}

